        var job = new JobbedLobpcgBSR { A = A, Cache = ws, K = k, Tol = Consts.doubleSqrtEps, MaxIter = 300, Out = outp };
        job.Run();

        var info = new LOBPCGInfo
        {
            iterations = outp[1],
            converged = outp[2],
            maxResidual = 0.0,
